settings.cellContentFunction:
value=(value.toString());
if (value === "1") {
    return '<div title = "FAULTY" style="border-radius:50%;background-color:red;width:11px;height:11px;font-size:0px">FAULTY</div>';
} else if (value === "0") {
    return '<div title = "OK" style="border-radius:50%;background-color:green;width:11px;height:11px;font-size:0px">OFF</div>';
} 
else {
    return "";
}

if (value != null && value != 0) {
    var d = new Date(value);
    const padZero = (num) => (num < 10 ? "0" + num : num);
    return padZero(d.getDate()) + "-" + 
           padZero(d.getMonth() + 1) + "-" + 
           d.getFullYear() + " " + 
           padZero(d.getHours()) + ":" + 
           padZero(d.getMinutes()) + ":" + 
           padZero(d.getSeconds());
} else {
    return value;
}

dataKeys.postFuncBody:
if (value != 0) {
    var currentDate = new Date();
    var earlierDate = new Date(value);

    // Get the difference in milliseconds
    var diffInMs = currentDate - earlierDate;

    // Ensure we don't have negative time if the date is in the future
    if (diffInMs < 0) { diffInMs = 0; }

    // Calculate time units
    var days = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    var hours = Math.floor((diffInMs / (1000 * 60 * 60)) % 24);
    var minutes = Math.floor((diffInMs / (1000 * 60)) % 60);
    var seconds = Math.floor((diffInMs / 1000) % 60);

    // Build the string dynamically
    var result = "";
    
    if (days > 0) {
        result += days + " days ";
    }
    if (hours > 0) {
        result += hours + " hr ";
    }
    if (minutes > 0) {
        result += minutes + " min ";
    }
    
    // Always show seconds, or show '0 sec' if everything is 0
    result += seconds + " sec";

    return result.trim();
} else {
    return value;
}

