headerButton.customFunction:
////Widget Header
let $injector = widgetContext.$scope.$injector;
let customDialog = $injector.get(widgetContext.servicesMap
    .get('customDialog'));
let attributeService = $injector.get(widgetContext
    .servicesMap.get('attributeService'));
let dialogs = $injector.get(widgetContext.servicesMap.get(
    'dialogs'));
var entityService = $injector.get(widgetContext.servicesMap
    .get('entityService'));
var device_name = [];
var sel_nonComm_names = ""; // names of devices which are selected for command and are non comm
var deviceList = [];
//var comm_val = [];
var deviceName = [];
//var comm_fail_val = [];
var deviceId = [];
var device_id = [];
var TargetCommand = {};
var observables = [];
var attributesArray = [];
var sliderValue;
openDimEntityDialog();

function openDimEntityDialog() {
    customDialog.customDialog(htmlTemplate,
        DimEntityDialogController).subscribe();
}

function DimEntityDialogController(instance) {
    let vm = instance;
    vm.entityName = entityName;
    vm.entityType = entityId.entityType;
    vm.dimValue = false;
    vm.dimSliderValue = 0;
    vm.selectedValue = 1;
    vm.selectedDate;
    vm.selectedTime;
    vm.minDate = new Date().toISOString().split("T")[0];

    vm.dimEntityFormGroup = vm.fb.group({
        entityName: ['', [vm.validators.required]],
        entityType: [null],
        dimValue: false,
        dimSliderValue: 0,
        selectedValue: 1,
        selectedDate: [new Date()],
        selectedTime: [''],
    });

    vm.cancel = function() {
        vm.dialogRef.close(null);
    };

    vm.disabled = function() {

        return ((vm.dimEntityFormGroup.get(
            'selectedValue').value) != 3);
    }

  vm.formatLabel=function(value) {
  sliderValue=value;
  return value;
}
   
    vm.save = function() {
        
        if (!(vm.dimEntityFormGroup.get('selectedValue')
                .value)) {
            showErrorDialog("Select an option");
            return;
        }
        let optionSelected = (vm.dimEntityFormGroup.get(
            'selectedValue').value);
        let cmd = "";
        if (optionSelected == 1) {
            cmd = "Turn On";
        } else if (optionSelected == 2) {
            cmd = "Turn Off";
        } else {
         
          if (!sliderValue)
         
          {
              showErrorDialog("Select Dim %.");
               
              return ;
          }
          cmd = "Dim";
        }
        ///select Date///
        if (!(vm.dimEntityFormGroup.get('selectedDate')
                .value)) {
            showErrorDialog("Select Expiration ");
            return;
        }
        let dateSelected = (vm.dimEntityFormGroup.get(
            'selectedDate').value);


        ///select Time///  
        if (!(vm.dimEntityFormGroup.get('selectedTime')
                .value)) {
            showErrorDialog("Select Time");
            return;
        }
        let timeSelected = (vm.dimEntityFormGroup.get(
            'selectedTime').value);

        //Change the selected to ISO String
        var date = new Date(dateSelected);
        var newDate = date.toLocaleDateString();
        newDate += " " + timeSelected;
        var isoDatetime = new Date(newDate);


        if (isoDatetime.getTime() <= new Date()
            .getTime()) {
            showErrorDialog(
                "Expiration time can not be less than current date-time."
            );
            return;
        }
         var content = 'Are you sure you want to '+cmd+' the lamp?' ;
     if (optionSelected == 3) {
        content = 'Are you sure you want to '+cmd+' the lamp to '+sliderValue+'%?' ;
     }
    var title = cmd;

        dialogs.confirm(title, content, 'Cancel', 'Yes')
            .subscribe(
                function(result) {
                    if (result) {
                        vm.dimEntityFormGroup
                            .markAsPristine();
                        let dateSelected = (vm
                            .dimEntityFormGroup.get(
                                'selectedDate')
                            .value);
                        TargetCommand.reason =
                            "override";
                        TargetCommand.expiration =
                            isoDatetime;
                        //attributesArray.push({key:"expiration",value:isoDatetime.toISOString()});

                        let timeSelected = (vm
                            .dimEntityFormGroup.get(
                                'selectedTime')
                            .value);

                        //attributesArray.push({key:"time",value:timeSelected });

                        let optionSelected = (vm
                            .dimEntityFormGroup.get(
                                'selectedValue')
                            .value);
                        if (optionSelected == 1) {
                            //attributesArray.push({key:"value", value:100});
                            TargetCommand['state'] = {
                                "name": "LevelState",
                                "value": 100
                            };
                        } else if (optionSelected ==
                            2) {
                            //attributesArray.push({key: "value", value:0 });
                            TargetCommand['state'] = {
                                "name": "LevelState",
                                "value": 0
                            };
                        } else {
                            // let sliderValue = vm
                            //     .dimEntityFormGroup.get(
                            //         'dimSliderValue')
                            //     .value;

                            // // attributesArray.push({key:"value", value:sliderValue });
                            // TargetCommand['state'] = {
                            //     "name": "LevelState",
                            //     "value": sliderValue
                            // };
                            TargetCommand['state']={"name":"LevelState","value":sliderValue};
                        }
                        
                        attributesArray.push({
                            key: "targetCommand",
                            value: TargetCommand
                        });
                        attributesArray.push({
                            key: "targetLightCommand",
                            value: TargetCommand
                        });
                        
                        getNLCForNonFailureCommunication();
                    }
                }

            );
        vm.dialogRef.close(null);
    };
  
}

function getNLCForNonFailureCommunication() {
        entityService.findEntityDataByQuery({
            "entityFilter": {
                "type": "entityType",
                "entityType": "DEVICE"
            },
            "keyFilters": [{
                "key": {
                    "type": "TIME_SERIES",
                    "key": "communicationFailure"
                },
                "valueType": "NUMERIC",
                "predicate": {
                    "operation": "EQUAL",
                    "value": {
                        "defaultValue": 1
                    },
                    "type": "NUMERIC"
                }
            }],
            "entityFields": [{
                "type": "ENTITY_FIELD",
                "key": "name"
            }],
            "latestValues": [{
                "type": "TIME_SERIES",
                "key": "communicationFailure"
            }],
            "pageLink": {
                "page": 0,
                "pageSize": 200,
                "sortOrder": {
                    "key": {
                        "key": "name",
                        "type": "ENTITY_FIELD"
                    },
                    "direction": "ASC"
                }
            }
        }).subscribe((response) => {
            const roots = response;
            for (var x in roots.data) {
                deviceName = roots.data[x].latest
                    .ENTITY_FIELD.name.value;
                device_name.push(deviceName);
                deviceId = roots.data[x].entityId
                    .id;
                device_id.push(deviceId);
            }
            deviceList = (device_name.join(', '));
            for (var val of widgetContext
                                .$scope.ctx
                                .defaultSubscription
                                .datasourcePages[0]
                                .data) {
                            
                            if (!device_id.includes(val.entity.id.id)) {
                                        observables.push(
                                    saveAttributes(
                                        attributesArray,
                                        val.entity
                                        .id)
                                );
                            } else {
                                var index = device_id.indexOf(val.entity.id.id);
                                if(sel_nonComm_names != "") {
                                    sel_nonComm_names = sel_nonComm_names+", ";
                                }
                                sel_nonComm_names = sel_nonComm_names+device_name[index];
                                
                            }
                        }
                        widgetContext.rxjs.forkJoin(
                            observables).subscribe(
                            data => {
                                 if(observables.length == deviceList.length) {
                                  showMessageDialog("Command has been submitted to the selected entities.");
                                 } else if (sel_nonComm_names != "") {
                                     showMessageDialog(
                "Command cannot be sent to these non-communicating NLCs:<br>" +
                sel_nonComm_names + ".");
                                 }

                            },
                            err => {
                                // console.error("Error",err);

                            }
                        );
        });
    }
    
function saveAttributes(attributesArray, entityId) {

    if (attributesArray.length > 0) {

        var returnVal = attributeService
            .saveEntityAttributes(entityId,
                "SHARED_SCOPE", attributesArray);
        return returnVal;
    }

    return widgetContext.rxjs.of([]);

}
function showErrorDialog(error) {
    let title = 'Error';

    dialogs.alert(title, error, 'CLOSE').subscribe(
        function(result) {}
    );
}

