let $injector = widgetContext.$scope.$injector;
let customDialog = $injector.get(widgetContext.servicesMap.get('customDialog'));
let attributeService = $injector.get(widgetContext.servicesMap.get('attributeService'));
var entityService = $injector.get(widgetContext.servicesMap.get('entityService'));
let dialogs = $injector.get(widgetContext.servicesMap.get('dialogs'));
var TargetCommand = {};
var attributesArray = [];
var EntityId = entityId.id;
var EntityType = entityId.entityType;
var comm_fail_device_name=[];
var comm_fail_device_id=[];
var observables =[];
var flag=false;
var sliderValue;
openDimEntityDialog();

function openDimEntityDialog() {
  customDialog.customDialog(htmlTemplate, DimEntityDialogController).subscribe();
}

function DimEntityDialogController(instance) {
  let vm = instance;
  vm.entityName = entityName;
  vm.entityType = entityId.entityType;
  vm.dimValue = false;
  vm.dimSliderValue = 0;
  vm.selectedValue = 1;
  vm.selectedDate;
  vm.selectedTime;
  vm.minDate = new Date().toISOString().split("T")[0];
  vm.dimEntityFormGroup = vm.fb.group({
    entityName: ['', [vm.validators.required]],
    entityType: [null],
    dimValue: false,
    dimSliderValue: 0,
    selectedValue: 1,
    selectedDate: [new Date()],
    selectedTime: [''],
  });

  vm.cancel = function () {
    vm.dialogRef.close(null);
  };

  vm.disabled = function () {

    return ((vm.dimEntityFormGroup.get('selectedValue').value) != 3);
  }
vm.formatLabel=function(value) {
 
  sliderValue=value;
  
  return value;
}
  vm.save = function () {
    var attributesArray = [];
    var observables = [];

    if (!(vm.dimEntityFormGroup.get('selectedValue').value)) {
      showErrorDialog("Select an option");
      return;
    }
    let optionSelected = (vm.dimEntityFormGroup.get('selectedValue').value);
    let cmd = "";
    if (optionSelected == 1) {
      cmd = "Turn On";
    } else if (optionSelected == 2) {
      cmd = "Turn Off";
    } else {
         
            // check this one
          if (!sliderValue)
         
          {
              showErrorDialog("Select Dim %.");
               
              return ;
          }
          cmd = "Dim";
          
      }
    ///select Date///
    if (!(vm.dimEntityFormGroup.get('selectedDate').value)) {
      showErrorDialog("Select Expiration ");
      return;
    }
    let dateSelected = (vm.dimEntityFormGroup.get('selectedDate').value);


    ///select Time///  
    if (!(vm.dimEntityFormGroup.get('selectedTime').value)) {
      showErrorDialog("Select Time");
      return;
    }
    let timeSelected = (vm.dimEntityFormGroup.get('selectedTime').value);

    //Change the selected to ISO String
    var date = new Date(dateSelected);
    var newDate = date.toLocaleDateString();
    newDate += " " + timeSelected;
    var isoDatetime = new Date(newDate);


    if (isoDatetime.getTime() <= new Date().getTime()) {
      showErrorDialog("Expiration time can not be less than current date-time.");
      return;
    }
    var content = 'Are you sure you want to '+cmd+' the lamp?' ;
     if (optionSelected == 3) {
        content = 'Are you sure you want to '+cmd+' the lamp to '+sliderValue+'%?' ;
     }
     var title = cmd;
    dialogs.confirm(title, content, 'Cancel', 'Yes').subscribe(
      function (result) {
        if (result) {
          vm.dimEntityFormGroup.markAsPristine();

          let dateSelected = (vm.dimEntityFormGroup.get('selectedDate').value);
          TargetCommand.reason = "override";
          TargetCommand.expiration = isoDatetime;
          //attributesArray.push({key:"expiration",value:dateSelected.toISOString()
          //attributesArray.push({key:"expiration",value:isoDatetime});
          let timeSelected = (vm.dimEntityFormGroup.get('selectedTime').value);

          //attributesArray.push({key:"time",value:timeSelected});

          let optionSelected = (vm.dimEntityFormGroup.get('selectedValue').value);
          if (optionSelected == 1) {
            //attributesArray.push({key:"value", value:100});
            TargetCommand['state'] = { "name": "LevelState", "value": 100 };
          } else if (optionSelected == 2) {
            //attributesArray.push({key: "value", value:0 });
            TargetCommand['state'] = { "name": "LevelState", "value": 0 };
          } else {
            TargetCommand['state']={"name":"LevelState","value":sliderValue};
          }
          getCommandNLCForNonFailureCommunication();
          vm.dialogRef.close(null);
        }
      }
      
    );
  };
  
  function getCommandNLCForNonFailureCommunication() {
    entityService.findEntityDataByQuery({
         "entityFilter": {
                "type": "singleEntity",
                "singleEntity": {
                     "id": EntityId,
                    "entityType":EntityType
                }
            },
        "keyFilters": [
            {
                "key": {
                    "type": "TIME_SERIES",
                    "key": "communicationFailure"
                },
                "valueType": "NUMERIC",
                "predicate": {
                    "operation": "EQUAL",
                    "value": {
                        "defaultValue": 1
                    },
                    "type": "NUMERIC"
                }
            }
        ],
        "entityFields": [
            {
                "type": "ENTITY_FIELD",
                "key": "name"
            }
        ],
        "latestValues": [
            {
                "type": "TIME_SERIES",
                "key": "communicationFailure"
            }
        ],
        "pageLink": {
            "page": 0,
            "pageSize": 200,
            "sortOrder": {
                "key": {
                    "key": "name",
                    "type": "ENTITY_FIELD"
                },
                "direction": "ASC"
            }
        }
    }).subscribe((response) => {
        
        const roots = response;
         if(roots.data.length>0)
        {
            flag=false;
            showMessageDialog(
                "Command cannot be sent to this non-communicating NLC:<br>" +
                entityName + ".");
        }
        else
        {
            flag=true;
            
        }
        for (var x in roots.data) {
            var deviceName = roots.data[x].latest.ENTITY_FIELD.name.value;
            comm_fail_device_name.push(deviceName);
            var deviceId = roots.data[x].entityId.id;
            comm_fail_device_id.push(deviceId);
            }
        var comm_fail_deviceList = (comm_fail_device_name.join(', '));
        if(flag)
 {
     
attributesArray.push({key:"targetCommand", value:TargetCommand});
attributesArray.push({key:"targetLightCommand", value:TargetCommand});
 observables.push(saveAttributes(attributesArray, entityId));
    }     
    widgetContext.rxjs.forkJoin(
                            observables).subscribe(
                            data => {
                                  showMessageDialog("Command has been submitted to the selected entity.");
                            },
                            
                            err => {
                                // console.error("Error",err);

                            }
                        );
        });
 
}
}
  function saveAttributes(attributesArray, entityId) {
    if (attributesArray.length > 0) {
      var returnVal = attributeService.saveEntityAttributes(entityId, "SHARED_SCOPE", attributesArray);
      return returnVal;
    }
    return widgetContext.rxjs.of([]);
  }
function showMessageDialog(msg) {
  let title = 'Turn On/Off/dim';
   
  dialogs.alert(title, msg, 'CLOSE').subscribe(
      function(result) {
          }
         
  );
}
function showErrorDialog(error) {
  let title = 'Error';

  dialogs.alert(title, error, 'CLOSE').subscribe(
    function (result) { }
  );
}

