openDeviceDialog();
function openDeviceDialog() {
    var title = 'End Override';
    var content = 'Are you sure you want to end override command?';
    dialogs.confirm(title, content, 'Cancel', 'End Override').subscribe(
        function (result) {
            if (result) {
                endOverrideCommandNLCForNonFailureCommunication(comm_fail_device_id);
            }
        }
    );
}
function saveAttributes(attributesArray, entityId) {
    if (attributesArray.length > 0) {
