    }
    return widgetContext.rxjs.of([]);
}
function endOverrideCommandNLCForNonFailureCommunication(comm_fail_device_id) {
    entityService.findEntityDataByQuery({
        "entityFilter": {
            "type": "singleEntity",
            "singleEntity": {
                "id": EntityId,
                "entityType": EntityType
            }
        },
        "keyFilters": [
            {
                "key": {
