                    "key": "communicationFailure"
                },
                "valueType": "NUMERIC",
                "predicate": {
                    "operation": "EQUAL",
                    "value": {
                        "defaultValue": 1
                    },
                    "type": "NUMERIC"
                }
            }
        ],
        "entityFields": [
            {
                "type": "ENTITY_FIELD",
                "key": "name"
            }
        ],
        "latestValues": [
            {
                "type": "TIME_SERIES",
