function DimEntityDialogController(instance) {
    let vm = instance;
    vm.entityName = entityName;
    vm.entityType = entityId.entityType;
    vm.supplyVoltage;
    vm.supplyCurrent;
    vm.activePower;
    //   vm.activeEnergy;
    vm.PhotocellStatus;
    vm.lightStateChange;
    vm.operatingHours;
    vm.actualLightState;
    vm.powerFactor;
    vm.LSC;
    vm.photocellOutput;
    vm.GpsStatus;
    vm.lampFailure;
    vm.RBCNT;
    vm.CumKwh;
    vm.Daily_kWh;
    vm.LampStatus;
    vm.switchOnCounter;
    vm.supplyVoltageTooHigh;
    vm.supplyVoltageTooLow;
    vm.feedbacklightcommand;
    vm.lampDriver;

    vm.dimEntityFormGroup = vm.fb.group({
        entityName: ['', [vm.validators.required]],
        entityType: [null],
        supplyVoltage: false,
        supplyCurrent: false,
        activePower: false,
        // activeEnergy:false,
        PhotocellStatus: false,
        lightStateChange: false,
        operatingHours: false,
        actualLightState: false,
        powerFactor: false,
        LSC: false,
        photocellOutput: false,
        GpsStatus: false,
        lampFailure: false,
        RBCNT: false,
        CumKwh: false,
        Daily_kWh: false,
        LampStatus: false,
        switchOnCounter: false,
        supplyVoltageTooHigh: false,
        supplyVoltageTooLow: false,
        feedbacklightcommand: false,
        lampDriver: false
    });


    vm.cancel = function () {
        vm.dialogRef.close(null);
    };

    //Get Select Parameters Button Code
    vm.getSelect = function () {

        var checkedValue = [];
        var inputElementsForMat = document.getElementsByClassName('mdc-checkbox--selected');
        //logic added here
        if (inputElementsForMat.length > 0) {
           for(var i=0; i< inputElementsForMat.length; i++) {
                checkedValue.push(inputElementsForMat[i]
                        .getAttribute('value'));
            }


        var content = 'Are you sure you want to get values of the selected parameters?';
        var title = "Get Command";
        dialogs.confirm(title, content, 'Cancel', 'Yes').subscribe(
            function (result) {
                if (result) {
                    vm.dimEntityFormGroup.markAsPristine();
                    
                    Invoke.reason = "get-data";
                    Invoke.Property = checkedValue;
                    attributesArray.push({ key: "Invoke", value: Invoke });
                    readDataForNonFailureCommunication();
                }
            }

        );
        vm.dialogRef.close(null);
        }
        else{
            showErrorDialog(
                "Select atleast one parameter."
            );
        }
    };

    function readDataForNonFailureCommunication() {
        entityService.findEntityDataByQuery({
            "entityFilter": {
                "type": "entityType",
                "entityType": "DEVICE"
            },
            "keyFilters": [{
                "key": {
                    "type": "TIME_SERIES",
                    "key": "communicationFailure"
                },
                "valueType": "NUMERIC",
                "predicate": {
                    "operation": "EQUAL",
                    "value": {
                        "defaultValue": 1
                    },
                    "type": "NUMERIC"
                }
            }],
            "entityFields": [{
                "type": "ENTITY_FIELD",
                "key": "name"
            }],
            "latestValues": [{
                "type": "TIME_SERIES",
                "key": "communicationFailure"
            }],
            "pageLink": {
                "page": 0,
                "pageSize": 200,
                "sortOrder": {
                    "key": {
                        "key": "name",
                        "type": "ENTITY_FIELD"
                    },
                    "direction": "ASC"
                }
            }
        }).subscribe((response) => {
            const roots = response;
            for (var x in roots.data) {
                deviceName = roots.data[x].latest
                    .ENTITY_FIELD.name.value;
                device_name.push(deviceName);
                deviceId = roots.data[x].entityId
                    .id;
                device_id.push(deviceId);
            }
            deviceList = (device_name.join(', '));
            for (var val of widgetContext
                .$scope.ctx
                .defaultSubscription
                .datasourcePages[0]
                .data) {

                if (!device_id.includes(val.entity.id.id)) {

                    observables.push(
                        saveAttributes(
                            attributesArray,
                            val.entity
                                .id)
                    );


                } else {
                    var index = device_id.indexOf(val.entity.id.id);
                    if (sel_nonComm_names != "") {
                        sel_nonComm_names = sel_nonComm_names + ", ";
                    }
                    sel_nonComm_names = sel_nonComm_names + device_name[index];

                }
            }
            widgetContext.rxjs.forkJoin(
                observables).subscribe(
                    data => {

                        if (observables.length == deviceList.length) {
                            showMessageDialog("Command has been submitted to the selected entities.");
                        } else if (sel_nonComm_names != "") {
                            showMessageDialog(
                                "Command cannot be sent to these non-communicating NLCs:<br>" +
                                sel_nonComm_names + ".");
                        }

                    },
                    err => {

                        // console.error("Error",err);

                    }
                );
        });
    }

    function saveAttributes(attributesArray, entityId) {

        if (attributesArray.length > 0) {

            var returnVal = attributeService
                .saveEntityAttributes(entityId,
                    "SHARED_SCOPE", attributesArray);
            return returnVal;
        }

        return widgetContext.rxjs.of([]);

    }

    //Get All Select parameters Button Code
    vm.getAllSelect = function () {
        var checkboxes = document.getElementsByName('property');
        var content = 'Are you sure you want to get values of all the parameters?';
        var title = "Get Command";
        dialogs.confirm(title, content, 'Cancel', 'Yes').subscribe(

            function (result) {
                if (result) {
                    vm.dimEntityFormGroup.markAsPristine();
                   Invoke.reason = "get-data";
                    attributesArray.push({ key: "Invoke", value: Invoke });
                    readDataForNonFailureCommunication();

                }
            }

        );
        vm.dialogRef.close(null);
    };

    function showErrorDialog(error) {
        let title = 'Error';

        dialogs.alert(title, error, 'CLOSE').subscribe(
            function (result) { }
        );
    }

    function showMessageDialog(msg) {
        let title = "Get Command";

        dialogs.alert(title, msg, 'CLOSE').subscribe(
            function (result) {
            }

        );
    }
}

