let dialogs = $injector.get(widgetContext.servicesMap.get('dialogs'));
var TargetCommand = {};
var attributesArray = [];
var sliderValue;
openDimEntityDialog();

function openDimEntityDialog() {
    if (additionalParams.entity.Comm == 1) {
        showErrorDialog("Command cannot be sent to non-communicating NLC.");
        return;
    }
    customDialog.customDialog(htmlTemplate, DimEntityDialogController).subscribe();
