function getReadAllCommandNLC() {
    entityService.findEntityDataByQuery({
        "entityFilter": {
            "type": "singleEntity",
            "singleEntity": {
                "id": EntityId,
                "entityType": EntityType
            }
        },
        "keyFilters": [{
            "key": {
                "type": "TIME_SERIES",
                "key": "communicationFailure"
            },
            "valueType": "NUMERIC",
            "predicate": {
                "operation": "EQUAL",
                "value": {
                    "defaultValue": 1
                },
                "type": "NUMERIC"
            }
        }],
        "entityFields": [{
            "type": "ENTITY_FIELD",
            "key": "name"
        }],
        "latestValues": [{
            "type": "TIME_SERIES",
            "key": "communicationFailure"
        }],
        "pageLink": {
            "page": 0,
            "pageSize": 200,
            "sortOrder": {
                "key": {
                    "key": "name",
                    "type": "ENTITY_FIELD"
                },
                "direction": "ASC"
            }
        }
    }).subscribe((response) => {
        const roots = response;
        if (roots.data.length > 0) {
            flag = false;
            showMessageDialog(
                "Command cannot be sent to this non-communicating NLC:<br>" +
                entityName + ".");
        } else {
            flag = true;

        }
        for (var x in roots.data) {
            var deviceName = roots.data[x].latest
                .ENTITY_FIELD.name.value;
            comm_fail_device_name.push(deviceName);
            var deviceId = roots.data[x].entityId
            .id;
            comm_fail_device_id.push(deviceId);
        }
        var comm_fail_deviceList = (
            comm_fail_device_name.join(', '));
        if (flag) {
            Invoke.reason = "get-data";
            attributesArray.push({
                key: "Invoke",
                value: Invoke
            });

            observables.push(saveAttributes(
                attributesArray, entityId));
        }
        widgetContext.rxjs.forkJoin(
            observables).subscribe(
            data => {
                
                showMessageDialog(
                    "Command has been submitted to the selected entity."
                    );
                //}
            },

            err => {

                // console.error("Error",err);

            }
        );
    });

}

function saveAttributes(attributesArray, entityId) {
    if (attributesArray.length > 0) {
        var returnVal = attributeService
            .saveEntityAttributes(entityId, "SHARED_SCOPE",
                attributesArray);
        return returnVal;
    }
    return widgetContext.rxjs.of([]);

}

function showMessageDialog(msg) {
    let title = 'Read Data';

    dialogs.alert(title, msg, 'CLOSE').subscribe(
        function(result) {}
    );
}

function showErrorDialog(error) {
    let title = 'Error';
    dialogs.alert(title, error, 'CLOSE').subscribe(
        function(result) {}
    );
}

