var comm_fail_device_name=[];
var comm_fail_device_id=[];
var observables =[];
var flag=false;
var sliderValue;
openDimEntityDialog();

function openDimEntityDialog() {
  customDialog.customDialog(htmlTemplate, DimEntityDialogController).subscribe();
}

function DimEntityDialogController(instance) {
  let vm = instance;
  vm.entityName = entityName;
  vm.entityType = entityId.entityType;
  vm.dimValue = false;
  vm.dimSliderValue = 0;
  vm.selectedValue = 1;
  vm.selectedDate;
  vm.selectedTime;
  vm.minDate = new Date().toISOString().split("T")[0];
  vm.dimEntityFormGroup = vm.fb.group({
    entityName: ['', [vm.validators.required]],
    entityType: [null],
    dimValue: false,
    dimSliderValue: 0,
    selectedValue: 1,
    selectedDate: [new Date()],
    selectedTime: [''],
  });

  vm.cancel = function () {
    vm.dialogRef.close(null);
  };

  vm.disabled = function () {

    return ((vm.dimEntityFormGroup.get('selectedValue').value) != 3);
  }
vm.formatLabel=function(value) {
 
  sliderValue=value;
  
  return value;
}
//jil added icon timepicker code
    // FLATPICKR INITIALIZATION
    vm.dialogRef.afterOpened().subscribe(function() {

        var timeInput = document.getElementById("timePicker");

        if (!timeInput) {
            console.error("timePicker element not found in HTML");
            return;
        }

        if (typeof flatpickr === "undefined") {
            console.error("Flatpickr JS not loaded. Add it in Resources tab.");
            return;
        }

        // Destroy old instance if dialog reopens (important in TB)
        if (timeInput._flatpickr) {
            timeInput._flatpickr.destroy();
        }

        flatpickr(timeInput, {
            enableTime: true,
            noCalendar: true,
            dateFormat: "h:i K", // 08:00 AM format (matches your parser)
            time_24hr: false,
            minuteIncrement: 1,
            allowInput: false,
            clickOpens: true,
            disableMobile: true, // VERY IMPORTANT for Firefox/Edge
            static: true, // Fix popup inside TB dialog
            defaultDate: new Date(),
            onChange: function(selectedDates, dateStr) {
                vm.dimEntityFormGroup.patchValue({
                    selectedTime: dateStr
                });
            }
        });
    });

    //


  vm.save = function () {
    var attributesArray = [];
    var observables = [];

    if (!(vm.dimEntityFormGroup.get('selectedValue').value)) {
      showErrorDialog("Select an option");
      return;
    }
    let optionSelected = (vm.dimEntityFormGroup.get('selectedValue').value);
    let cmd = "";
    if (optionSelected == 1) {
      cmd = "Turn On";
    } else if (optionSelected == 2) {
      cmd = "Turn Off";
    } else {
         
            // check this one
          if (!sliderValue)
         
          {
              showErrorDialog("Select Dim %.");
               
              return ;
          }
          cmd = "Dim";
          
      }
    ///select Date///
    if (!(vm.dimEntityFormGroup.get('selectedDate').value)) {
      showErrorDialog("Select Expiration ");
      return;
    }
    let dateSelected = (vm.dimEntityFormGroup.get('selectedDate').value);


    ///select Time///  
    if (!(vm.dimEntityFormGroup.get('selectedTime').value)) {
      showErrorDialog("Select Time");
      return;
    }
    let timeSelected = (vm.dimEntityFormGroup.get('selectedTime').value);
    //below logic is for apply 12 hous and 24 hours --JIL
        function parseTimeTo24Hour(timeStr) {
            if (!timeStr) return {
                hours: 0,
                minutes: 0
            };

            timeStr = timeStr.trim();

            // Check 12-hour format (AM/PM)
            var ampmMatch = timeStr.match(/(\d{1,2}):(\d{2})\s*(AM|PM)/i);
            if (ampmMatch) {
                var hours = parseInt(ampmMatch[1], 10);
                var minutes = parseInt(ampmMatch[2], 10);
                var ampm = ampmMatch[3].toUpperCase();

                if (ampm === "PM" && hours < 12) hours += 12;
                if (ampm === "AM" && hours === 12) hours = 0;

                return {
                    hours: hours,
                    minutes: minutes
                };
            }

            // 24-hour format (HH:mm)
            var parts = timeStr.split(":");
            return {
                hours: parseInt(parts[0], 10) || 0,
                minutes: parseInt(parts[1], 10) || 0
            };
        }

        // Create base date safely (no locale parsing)
        var baseDate = new Date(dateSelected);

        // Parse time (supports 12hr & 24hr)
        var timeObj = parseTimeTo24Hour(timeSelected);

        // Set hours & minutes directly (browser-safe)
        baseDate.setHours(timeObj.hours);
        baseDate.setMinutes(timeObj.minutes);
        baseDate.setSeconds(0);
        baseDate.setMilliseconds(0);

        // Final ISO datetime (absolute correct)
        var isoDatetime = baseDate.toISOString();

        // Validation (absolute reliable)
        if (baseDate.getTime() <= new Date().getTime()) {
            showErrorDialog("Expiration time can not be less than current date-time.");
            return;
        }

    // //Change the selected to ISO String
    // var date = new Date(dateSelected);
    // var newDate = date.toLocaleDateString();
    // newDate += " " + timeSelected;
    // var isoDatetime = new Date(newDate);


    // if (isoDatetime.getTime() <= new Date().getTime()) {
    //   showErrorDialog("Expiration time can not be less than current date-time.");
    //   return;
    // }
    var content = 'Are you sure you want to '+cmd+' the lamp?' ;
     if (optionSelected == 3) {
        content = 'Are you sure you want to '+cmd+' the lamp to '+sliderValue+'%?' ;
     }
     var title = cmd;
    dialogs.confirm(title, content, 'Cancel', 'Yes').subscribe(
      function (result) {
        if (result) {
          vm.dimEntityFormGroup.markAsPristine();

          let dateSelected = (vm.dimEntityFormGroup.get('selectedDate').value);
          TargetCommand.reason = "override";
          TargetCommand.expiration = isoDatetime;
          //attributesArray.push({key:"expiration",value:dateSelected.toISOString()
          //attributesArray.push({key:"expiration",value:isoDatetime});
          let timeSelected = (vm.dimEntityFormGroup.get('selectedTime').value);

          //attributesArray.push({key:"time",value:timeSelected});

          let optionSelected = (vm.dimEntityFormGroup.get('selectedValue').value);
          if (optionSelected == 1) {
            //attributesArray.push({key:"value", value:100});
            TargetCommand['state'] = { "name": "LevelState", "value": 100 };
          } else if (optionSelected == 2) {
            //attributesArray.push({key: "value", value:0 });
            TargetCommand['state'] = { "name": "LevelState", "value": 0 };
          } else {
            TargetCommand['state']={"name":"LevelState","value":sliderValue};
          }
          getCommandNLCForNonFailureCommunication();
          vm.dialogRef.close(null);
        }
      }
      
    );
  };
  
  function getCommandNLCForNonFailureCommunication() {
    entityService.findEntityDataByQuery({
         "entityFilter": {
